"""BOLA / IDOR + missing-authorization evaluation.

This is the *trust & logic* experiment: classic taint analysis is structurally
blind to BOLA/IDOR (the object selector is a clean, cast value) and to missing
authorization (the data may even be tainted, but the bug is the absent privilege
boundary). MANIFOLD's structural signal --- an ungated, user-controlled resource
access --- is what surfaces them.

Two corpora:

* ``examples/python/bola/`` (n=6, hand-picked) --- a *feasibility* signal.
* ``examples/python/bola_corpus/`` (n=40, generated by ``gen_bola_corpus.py``,
  default) --- a larger, structurally diverse, *adversarial* corpus that
  includes sanitized / parameterized / unused-source cases the structural
  heuristic should get wrong; this is what makes the measured precision honest.

The corpus is synthetic/curated; we report precision/recall as an honest
feasibility + robustness signal, not a production benchmark.
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from manifold.analysis.authorization import bola_idor_candidates  # noqa: E402
from manifold.ingest.python import PythonIngest  # noqa: E402

SMALL = ROOT / "examples" / "python" / "bola"
SMALL_LABELS = {
    "idor_vuln.py": True,
    "idor_fixed_gate.py": False,
    "idor_fixed_ownership.py": False,
    "cwe862_vuln.py": True,
    "cwe862_fixed.py": False,
    "benign.py": False,
}


def load_labels(corpus: Path) -> dict:
    manifest = corpus / "manifest.json"
    if manifest.exists():
        return json.loads(manifest.read_text())
    return SMALL_LABELS if corpus == SMALL else {}


def evaluate(corpus: Path) -> dict:
    labels = load_labels(corpus)
    tp = fp = fn = tn = 0
    rows = []
    for name, vulnerable in sorted(labels.items()):
        path = corpus / name
        # fresh ingest per file: the adapter keeps per-analysis state
        result = PythonIngest().analyze(path.read_text(), path=name)
        cands = bola_idor_candidates(result.graph)
        predicted = len(cands) > 0
        tp += predicted and vulnerable
        fp += predicted and not vulnerable
        fn += (not predicted) and vulnerable
        tn += (not predicted) and not vulnerable
        rows.append({
            "file": name, "vulnerable": vulnerable, "predicted": predicted,
            "n_candidates": len(cands), "categories": sorted({c.category for c in cands}),
        })
    precision = tp / (tp + fp) if (tp + fp) else 0.0
    recall = tp / (tp + fn) if (tp + fn) else 0.0
    f1 = 2 * precision * recall / (precision + recall) if (precision + recall) else 0.0
    return {"precision": precision, "recall": recall, "f1": f1,
            "tp": tp, "fp": fp, "fn": fn, "tn": tn, "n": len(labels), "rows": rows}


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--corpus", choices=["small", "large"], default="large")
    args = ap.parse_args()
    corpus = SMALL if args.corpus == "small" else ROOT / "examples" / "python" / "bola_corpus"

    res = evaluate(corpus)
    print(f"== BOLA / IDOR + missing-authorization ({args.corpus} corpus, n={res['n']}) ==")
    for r in res["rows"]:
        mark = "" if r["predicted"] == r["vulnerable"] else "   <-- ERROR"
        print(f"  {r['file']:<26} vuln={int(r['vulnerable'])} pred={int(r['predicted'])} "
              f"cands={r['n_candidates']} {r['categories']}{mark}")
    print(f"\n  TP={res['tp']} FP={res['fp']} FN={res['fn']} TN={res['tn']}")
    print(f"  precision={res['precision']:.3f} recall={res['recall']:.3f} F1={res['f1']:.3f}")
    fp_files = [r["file"] for r in res["rows"] if r["predicted"] and not r["vulnerable"]]
    if fp_files:
        print(f"  false positives (heuristic limits): {', '.join(fp_files)}")

    out = ROOT / "benchmarks" / "bola_results.json"
    out.write_text(json.dumps({"corpus": args.corpus, **res}, indent=2))
    print(f"  results -> {out.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
